import json, random, string

# Generate qpdf-compatible JSON structures and other valid JSON variants.
# The fuzzer stubs consume UTF-8 strings from FUZZ_PARAM_STR for multiple entry points:
#  - QPDF::createFromJSON / updateFromJSON expect qpdf JSON (prefer version>=2)
#  - QPDFJob::initializeFromJson expects job JSON (version 1)
#  - C API qpdf_create_from_json_data / qpdf_update_from_json_data expect qpdf JSON
#  - qpdfjob_* also accept job JSON
# We therefore probabilistically emit:
#  - Full qpdf JSON document (schema-like) with objects, trailer, xref, streams
#  - Partial qpdf JSON snippets suitable for updateFromJSON
#  - Job JSON describing inputs/outputs and options
#  - Small generic JSONs (arrays, numbers, strings) to exercise tolerant paths
# Limit size to <= 4096 bytes.

MAX_BYTES = 4096

RANGE_STR_CHARS = string.ascii_letters + string.digits + "_-/.+ \t"


def _rand_str(r: random.Random, min_len=0, max_len=24):
    n = r.randint(min_len, max_len)
    # include some unicode to test UTF-8 handling
    extra = ["✓", "Σ", "漢", "é", "—", "•"]
    s = "".join(r.choice(RANGE_STR_CHARS) for _ in range(max(0, n - 1)))
    if n > 0:
        s += r.choice(extra) if r.random() < 0.3 else r.choice(RANGE_STR_CHARS)
    return s.strip() or "x"


def _rand_int(r: random.Random, bits=31):
    # cover small and large values
    choices = [0, 1, -1, 2**16 - 1, 2**31 - 1, -2**31]
    if r.random() < 0.6:
        return r.randint(-(2**bits), 2**bits - 1)
    return r.choice(choices)


def _name_obj(r: random.Random):
    # PDF name like /Type -> in JSON it is plain string without slash
    return r.choice(["Type", "Root", "Pages", "Kids", "Count", "MediaBox", "Contents", "Resources"])  # simple


def _pdf_rect(r: random.Random):
    # [llx, lly, urx, ury]
    w = r.randint(100, 800)
    h = r.randint(100, 1000)
    return [0, 0, w, h]


def _stream_dict(r: random.Random, objid: int):
    # Basic stream object representation for qpdf JSON
    data_variants = [
        "BT /F1 12 Tf 72 720 Td (Hello) Tj ET",
        json.dumps({"k": _rand_str(r, 3, 12)}),
        "eJzT0yMAAGTvA4Q=",  # looks like base64
    ]
    filters = [
        [],
        ["FlateDecode"],
        ["ASCIIHexDecode"],
        ["RunLengthDecode"],
    ]
    d = {
        "_obj": objid,
        "type": "stream",
        "dict": {
            "Length": 0,  # qpdf can compute if mismatched
            "Filter": r.choice(filters),
        },
        "data": r.choice(data_variants),
        "encode": r.choice([False, True]),
    }
    return d


def _page_obj(r: random.Random, objid: int, contents_ref: int):
    return {
        "_obj": objid,
        "type": "dictionary",
        "value": {
            "Type": "Page",
            "Parent": {"ref": 2, "gen": 0},
            "MediaBox": _pdf_rect(r),
            "Contents": {"ref": contents_ref, "gen": 0},
            "Resources": {
                "Font": {"F1": {"ref": 7, "gen": 0}}
            },
        },
    }


def _font_obj(objid: int):
    return {
        "_obj": objid,
        "type": "dictionary",
        "value": {
            "Type": "Font",
            "Subtype": "Type1",
            "BaseFont": "Helvetica",
            "Encoding": "WinAnsiEncoding",
        },
    }


def _pages_obj(r: random.Random, kids):
    return {
        "_obj": 2,
        "type": "dictionary",
        "value": {
            "Type": "Pages",
            "Count": len(kids),
            "Kids": [{"ref": kid, "gen": 0} for kid in kids],
        },
    }


def _catalog_obj():
    return {
        "_obj": 1,
        "type": "dictionary",
        "value": {
            "Type": "Catalog",
            "Pages": {"ref": 2, "gen": 0},
        },
    }


def _xref_table(objs):
    table = {}
    off = 100  # arbitrary increasing offsets
    for o in objs:
        table[str(o)] = {"type": 1, "offset": off, "gen": 0}
        off += 50
    return table


def build_qpdf_json_full(r: random.Random):
    # Build a small but valid-ish qpdf JSON document (schema v2)
    # Object ids: 1=Catalog, 2=Pages, 3=Page, 4=Contents stream, 7=Font
    contents = _stream_dict(r, 4)
    page = _page_obj(r, 3, 4)
    pages = _pages_obj(r, [3])
    catalog = _catalog_obj()
    font = _font_obj(7)
    objs = [catalog, pages, page, contents, font]

    j = {
        "qpdf": 2,
        "version": "1.7",
        "objects": objs,
        "xref": _xref_table([1, 2, 3, 4, 7]),
        "trailer": {
            "Root": {"ref": 1, "gen": 0},
            "Size": 8,
            "ID": [
                "0123456789abcdef0123456789abcdef",
                "fedcba9876543210fedcba9876543210",
            ],
        },
        "encrypt": None,
    }
    return j


def build_qpdf_json_update(r: random.Random):
    # Partial update: change page contents or add an object
    op = r.choice(["replace-object", "add-object", "set-trailer", "set-root-version"])
    if op == "replace-object":
        return {"objects": [_stream_dict(r, 4)]}
    if op == "add-object":
        new_id = r.randint(10, 50)
        return {"objects": [_stream_dict(r, new_id)]}
    if op == "set-trailer":
        return {"trailer": {"Info": {"Producer": _rand_str(r, 3, 16)}}}
    # set-root-version
    return {"version": f"1.{r.randint(3,7)}"}


def build_job_json(r: random.Random):
    # QPDFJob::initializeFromJson expects job JSON schema v1
    # Provide minimal required fields with optional knobs
    infile = "/tmp/" + _rand_str(r, 3, 10) + ".pdf"
    outfile = "/tmp/" + _rand_str(r, 3, 10) + ".pdf"
    job = {
        "qpdfjob": 1,
        "inputFile": infile,
        "outputFile": outfile,
    }
    # Randomly add options
    if r.random() < 0.5:
        job["replaceInput"] = r.choice([True, False])
    if r.random() < 0.5:
        job["pages"] = [
            {"file": infile, "range": r.choice(["1-", "1-2", "odd", "even"])},
        ]
    if r.random() < 0.5:
        job["encrypt"] = {
            "keylen": r.choice([40, 128, 256]),
            "userPassword": _rand_str(r, 0, 8),
            "ownerPassword": _rand_str(r, 0, 8),
        }
    if r.random() < 0.5:
        job["global"] = {"inspectionMode": r.choice([True, False])}
    return job


def build_generic_json(r: random.Random):
    # Small valid JSONs to exercise tolerant paths
    variants = [
        lambda: {"note": _rand_str(r, 0, 40)},
        lambda: [_rand_int(r) for _ in range(r.randint(0, 6))],
        lambda: True,
        lambda: None,
        lambda: {"array": [
            {"k": _rand_str(r, 1, 6)},
            _rand_int(r),
            r.random(),
        ]},
    ]
    return r.choice(variants)()


def pick_document(r: random.Random):
    # Weighted selection across formats
    roll = r.random()
    if roll < 0.45:
        return build_qpdf_json_full(r)
    if roll < 0.70:
        return build_qpdf_json_update(r)
    if roll < 0.88:
        return build_job_json(r)
    return build_generic_json(r)


def serialize_limited(doc) -> bytes:
    s = json.dumps(doc, ensure_ascii=False, separators=(",", ":"))
    b = s.encode("utf-8")
    if len(b) <= MAX_BYTES:
        return b
    # If too large, fall back to a compact partial: keep top-level keys minimal
    if isinstance(doc, dict):
        small = {}
        for k in doc:
            small[k] = doc[k]
            bs = json.dumps(small, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            if len(bs) > MAX_BYTES:
                del small[k]
                break
        return json.dumps(small, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    # Arrays or scalars: truncate array or stringify
    if isinstance(doc, list):
        out = []
        for v in doc:
            out.append(v)
            bs = json.dumps(out, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            if len(bs) > MAX_BYTES:
                out.pop()
                break
        return json.dumps(out, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return b[:MAX_BYTES]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    doc = pick_document(r)
    return serialize_limited(doc)
